var lightDir = Math.PI * 0.25;
var lightVec;
var x, y, rot, radius;
var colorHue, colorSat;
var polygonAngles = 3;
var minLen, bleed;
var _frameCount;

function setup() {
	createCanvas(windowWidth, windowHeight);
	colorMode(HSB, 360, 100, 100, 100);
	noiseDetail(12, 0.025);
	background(0);

	minLen = max(width, height);
	bleed = 2;
	lightVec = p5.Vector.fromAngle(lightDir);
	polygonAngles = floor(random(3,9));
	colorHue = random(360);
	colorSat = 65;

	rot = 0;
	radius = minLen * 0.07;
	x = width / 2;
	y = -radius;


	_frameCount = 0;
}

function draw() {
	const frameEnd = Date.now() + 1000 / 60;
	let maxIterations = 50;

	while (frameEnd > Date.now() && maxIterations--) {
		_frameCount++;
		rot += 0.0025;
		const effectiveRadius = radius + map(sin(_frameCount / 1000), -1, 1, -0.75, 0.5) * radius;

		const pos = createVector(x/width*2-1 + _frameCount*0.00001, y/height*2-1  + _frameCount*0.00001);

		//const dir = p5.Vector.fromAngle(noise(pos.x, pos.y, _frameCount * 0.0003) * TWO_PI * 4).mult(0.5);
		const dir = p5.Vector.fromAngle(noise(_frameCount * 0.0007) * TWO_PI * 4).mult(0.5);
		x += dir.x;
		y += dir.y;

		const colorT = abs((floor(_frameCount) % 200000)/100000-1);
		strokeWeight(1.5);
		drawPolygon(x, y, rot, effectiveRadius, polygonAngles, colorT);

		if (x + effectiveRadius < -bleed) {
			if(checkStop(colorT)) break;
			x = width + effectiveRadius;
		}
		if (x - effectiveRadius > width + bleed) {
			if(checkStop(colorT)) break;
			x = -effectiveRadius;
		}
		if (y + effectiveRadius < -bleed) {
			if(checkStop(colorT)) break;
			y = height + effectiveRadius;
		}
		if (y - effectiveRadius > height + bleed) {
			if(checkStop(colorT)) break;
			y = -effectiveRadius;
		}
	}
}

function checkStop(colorT){
	_frameCount += random(3,33);
	return false;
	if(colorT > 1.1) {
		// noLoop() removed for animation
		return true;	 
	}
	return false;
}

function drawPolygon(cx, cy, rot, radius, pointCount, colorT) {
	const flapSize = radius*0.5;
	const innerRadius = radius - flapSize;
	const effectiveFlapSize = flapSize * map(sin(_frameCount/33), -1, 1, 0.5, 1);

	for (let i = 0; i < pointCount; i++) {
		const ti = i/pointCount;
		const angle = ti * TWO_PI + rot;
		const nextAngle = (i + 1) / pointCount * TWO_PI + rot;
		const thisX = cos(angle);
		const thisY = sin(angle);
		const nextX = cos(nextAngle);
		const nextY = sin(nextAngle);

		const normal = createVector((thisX + nextX) / 2, (thisY + nextY) / 2);
		const shade = 1 - (normal.dot(lightVec) + 1) / 2;

		const col = color((colorHue+360+colorT*25+sin(_frameCount*0.0004)*35)%360, colorSat-shade**2*30, shade*(80 + sin(_frameCount*0.005+ti*TWO_PI)*20));//color((colorHue + i * 45) % 360, colorSat - shade ** 2 * 30, shade * 1 * 95);
		strokeWeight(1.5);
		//stroke(lerpColor(color(0), col, colorT));
		stroke(col);
		line(cx + thisX * innerRadius, cy + thisY * innerRadius, cx + nextX * innerRadius, cy + nextY * innerRadius);

		stroke(hue(window.color(col)),saturation(window.color(col))*0.25,90 * shade*2+40,10);
		strokeWeight(2);
		push();
		translate(cx+thisX*innerRadius, cy+thisY*innerRadius);
		rotate(sin(_frameCount/20)*PI*0.1);
		line(0,0,thisX*effectiveFlapSize, thisY*effectiveFlapSize);
		pop();
		//point(cx+thisX*radius, cy+thisY*radius);
	}
}
